#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr putTest ();OSErr putTest (){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	char	*theTexture;	long	theSize, theWidth, theHeight;	StandardFileReply	theReply;	SFTypeList			theTypeList = { 0, 0, 0, 0 };	Point myPoint;	_256Header thePlugHeader;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// new plug file	SetPt ( &myPoint, -1, -1);	CustomGetFile ( nil, 0, theTypeList, &theReply, 4001, myPoint,  nil, nil, nil, nil, nil );	if ( theReply.sfGood != true )		return -1;	theError = FSpOpenDF ( &theReply.sfFile, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	FileRead ( &thePlugHeader, sizeof( _256Header ), thePlugFileRef );	if ( thePlugHeader.type != '.256' ){		ParamText( "\pNot a valid .256 file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		return -1;	}	theWidth = 256;	theHeight = 256;	theSize = theWidth * theHeight;	theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, 384L );					// get the current palette.	FileRead ( &thePalette, 2080L, thePlugFileRef );	theError = readBMP ( "\p:Graphics.in:test.bmp", theWidth, theHeight, &thePalette, theTexture );	if ( theError != noErr ){		DisposePtr ( (Ptr) theTexture );		FSClose ( thePlugFileRef );		return theError;	}	FileSeek ( thePlugFileRef, 384L );	FileWrite ( &thePalette, 2080L, thePlugFileRef );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return	noErr;}